const item = $input.first().json;
const src = (item.body && typeof item.body === 'object') ? item.body : item;
const first = String(src.first_name || src.firstName || '');
const last = String(src.last_name || src.lastName || '');
const combined = `${first} ${last}`.trim();
const fullName = String(src.full_name || src.name || combined || '').trim();
const start = src.start_run;
const extra = (src.extra && typeof src.extra === 'object') ? src.extra : {};

return [{
  json: {
    email: String(src.email || '').trim().toLowerCase(),
    full_name: fullName,
    company: src.company || null,
    title: src.title || src.job_title || null,
    website: src.website || src.domain || null,
    phone: src.phone || src.phone_number || null,
    notes: src.notes || src.message || null,
    extra: { ...extra, n8n_execution_id: $execution.id },
    external_id: String(src.external_id || src.id || `n8n-${$execution.id}`),
    start_run: !(start === false || start === 'false' || start === 0),
  },
}];
